local L=game:GetService("Lighting"); local C=workspace.Terrain:WaitForChild("Clouds"); local day=Color3.fromRGB(239,247,255); local dawn=Color3.fromRGB(255,211,178); local sunset=Color3.fromRGB(255,170,132); local night=Color3.fromRGB(128,146,177); local function target(h) if h>=16 and h<=20 then return day:Lerp(sunset,math.clamp(1-math.abs(h-18)/2,0,1)) elseif h>=20 and h<=21 then return sunset:Lerp(night,h-20) elseif h>21 or h<5 then return night elseif h>=5 and h<=6.5 then return night:Lerp(dawn,math.clamp((h-5)/1.5,0,1)) elseif h>6.5 and h<8 then return dawn:Lerp(day,(h-6.5)/1.5) end return day end; while true do C.Color=C.Color:Lerp(target(L.ClockTime),0.04); task.wait(0.5) end